import os
import requests

def select_voice(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.getenv("ELEVENLABS_API_KEY")
    target_locale = payload.get("locale") or payload.get("target_locale") or payload.get("language")
    headers = {
        "Accept": "application/json",
        "xi-api-key": api_key or "",
    }
    params = {}
    if target_locale:
        params["locale"] = target_locale
    response = requests.get("https://api.elevenlabs.io/v1/voices", headers=headers, params=params, timeout=config.get("timeout", 30))
    response.raise_for_status()
    result = response.json()
    return result
